import{_ as o,o as t,c as d,a0 as r}from"./chunks/framework.B6reNh8h.js";const f=JSON.parse('{"title":"Config","description":"","frontmatter":{},"headers":[],"relativePath":"reference/config.md","filePath":"reference/config.md"}'),c={name:"reference/config.md"};function a(n,e,i,s,l,h){return t(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="config" tabindex="-1">Config <a class="header-anchor" href="#config" aria-label="Permalink to &quot;Config&quot;">​</a></h1><p>Host/product configuration for the pavo suite flows through the <strong>config API</strong> — <code>tamias-driver-config</code>, a first-party driver that answers namespaced <code>query</code> ops over the <code>serve</code> wire. There is no <code>pavo.toml</code> read directly by the host; drivers and products query the config driver (or adopt the API natively later).</p><p>Full contract: <code>crates/pavo-driver-config/README.md</code>; usage: <a href="/pavo/how-to/use-config-api.html">Use the config API</a>.</p><h2 id="queries" tabindex="-1">Queries <a class="header-anchor" href="#queries" aria-label="Permalink to &quot;Queries&quot;">​</a></h2><table tabindex="0"><thead><tr><th>query</th><th>params</th><th>returns</th></tr></thead><tbody><tr><td><code>get</code></td><td><code>key</code> (dotted)</td><td><code>{key, value, found}</code></td></tr><tr><td><code>set</code></td><td><code>key</code>, <code>value</code></td><td><code>{key, value, path, written}</code></td></tr><tr><td><code>resolve</code></td><td>—</td><td>merged config tree (nested JSON)</td></tr><tr><td><code>config</code></td><td>—</td><td>merged config flattened to dotted keys</td></tr><tr><td><code>sources</code></td><td>—</td><td>every contributing layer, in precedence order</td></tr></tbody></table><p>Keys are namespaced dotted paths (<code>myco.theme</code>, <code>kuda.index</code>) — callers never read config files directly.</p><h2 id="layers-low-→-high-precedence" tabindex="-1">Layers (low → high precedence) <a class="header-anchor" href="#layers-low-→-high-precedence" aria-label="Permalink to &quot;Layers (low → high precedence)&quot;">​</a></h2><ol><li><strong>defaults</strong> — <code>theme=dark</code>, <code>statusbar=true</code>, <code>refresh_ms=5000</code></li><li><strong>global</strong> — <code>$XDG_CONFIG_HOME/pavo/pavo.{toml,json}</code> or <code>~/.config/pavo/pavo.{toml,json}</code></li><li><strong>project</strong> — <code>pavo.toml</code> and <code>pavo.json</code> in every ancestor of the cwd, filesystem root → cwd (nearest file wins)</li><li><strong>explicit</strong> — <code>--config &lt;path&gt;</code> on argv (manual <code>serve</code> only) or <code>$PAVO_CONFIG</code></li><li><strong>env</strong> — <code>PAVO_CONFIG_*</code> scalar overrides</li></ol><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Var</th><th>Meaning</th></tr></thead><tbody><tr><td><code>TAMIAS_HOME</code></td><td>tamias home override — also the default drivers dir parent (<code>$TAMIAS_HOME/drivers</code>)</td></tr><tr><td><code>XDG_DATA_HOME</code></td><td>fallback parent for <code>&lt;tamias-home&gt;</code> (<code>$XDG_DATA_HOME/tamias</code>)</td></tr><tr><td><code>XDG_CONFIG_HOME</code></td><td>fallback parent for global config (<code>$XDG_CONFIG_HOME/pavo/</code>)</td></tr><tr><td><code>PAVO_CONFIG</code></td><td>explicit config file path for <code>tamias-driver-config</code></td></tr><tr><td><code>PAVO_CONFIG_*</code></td><td>env overrides — <code>PAVO_CONFIG_THEME=light</code> → <code>theme</code>; <code>PAVO_CONFIG_MYCO__THEME=x</code> → <code>myco.theme</code> (<code>__</code> = dot, <code>_</code> = literal underscore); values parse as JSON when possible</td></tr><tr><td><code>PAVO_WEB_DIR</code></td><td><code>pavo serve</code> static web-root override</td></tr><tr><td><code>NUXT_PUBLIC_PAVO_API</code></td><td>web app: absolute bridge base (empty = same-origin <code>/api</code>)</td></tr><tr><td><code>PAVO_API_TARGET</code></td><td><code>nuxt dev</code> only: <code>/api/*</code> proxy target</td></tr><tr><td><code>NITRO_PRESET</code></td><td>web build: <code>static</code> (default) or <code>node-server</code></td></tr></tbody></table><h2 id="formats" tabindex="-1">Formats <a class="header-anchor" href="#formats" aria-label="Permalink to &quot;Formats&quot;">​</a></h2><p><strong>TOML</strong> and <strong>JSON</strong> only — no YAML dependency in the workspace tree. <code>.yaml</code>/<code>.yml</code> files surface as <code>error</code> rows in <code>sources</code> rather than being silently misparsed.</p><p><code>set</code> writes the project-level file (explicit path → nearest <code>pavo.toml</code>/<code>pavo.json</code> → fresh <code>./pavo.toml</code>); TOML writes preserve comments via <code>toml_edit</code>. <code>null</code> and nested objects can&#39;t be stored in TOML — use dotted keys for tables.</p>',13)])])}const g=o(c,[["render",a]]);export{f as __pageData,g as default};
